import math

def check_candidate(q):
    # Calculate the expression under the cube root: q^2 - q + 1
    expr = q**2 - q + 1

    # Calculate the cube root
    try:
        # Check if expr is a perfect cube
        root = round(expr**(1/3))
        if root**3 == expr:
            p = root
            # Check if p is prime
            def is_prime(n):
                if n < 2:
                    return False
                for i in range(2, int(math.sqrt(n)) + 1):
                    if n % i == 0:
                        return False
                return True

            is_p_prime = is_prime(p)
            is_q_prime = is_prime(q)

            if is_q_prime and is_p_prime and p != q:
                print(f"q={q}: E={p}. Conditions met.")
                return True
            else:
                print(f"q={q}: Conditions failed (p={p} or q={q} not prime or p=q).")
                return False
        else:
            print(f"q={q}: Expression {expr} is not a perfect cube.")
            return False
    except OverflowError:
        print(f"q={q}: Calculation error.")
        return False

